"use strict";

const createGitRepositoryService = require("./lib/git-repos");

module.exports = function(RED) {
    const {listRepositories, resolveRepository, fetchRemotes} = createGitRepositoryService(RED.settings);

    function GitFetchNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on("input", async function(msg, send, done) {
            try {
                let repositories;
                if (config.mode === "repository") {
                    const name = RED.util.evaluateNodeProperty(config.repository || "payload.repository", config.repositoryType || "msg", node, msg);
                    repositories = [await resolveRepository(name)];
                } else if (!config.mode || config.mode === "all") {
                    repositories = await listRepositories();
                } else {
                    throw new Error("Unsupported Git fetch mode");
                }
                node.status({fill: "blue", shape: "dot", text: "fetching"});
                for (const repository of repositories) {
                    await fetchRemotes(repository.path);
                }
                node.status({});
                send(msg);
                done();
            } catch (error) {
                node.status({fill: "red", shape: "ring", text: "Git fetch failed"});
                done(error);
            }
        });
    }

    RED.nodes.registerType("git fetch", GitFetchNode);
};
